node -e '
const fs=require("fs");
const regions=["north","south","east","west"];
const inspector={north:{count:10,units:90,weighted:167},south:{count:10,units:94,weighted:171},east:{count:10,units:98,weighted:209},west:{count:10,units:85,weighted:145}};
const out={regions:{},grand_units:0,grand_weighted:0};
let ok=true;
for(const r of regions){
  const raw=fs.readFileSync(r+".json","utf8");
  const data=JSON.parse(raw);
  if(!Array.isArray(data)) throw new Error(r+" not array");
  let units=0,weighted=0; const ids=new Set();
  for(const [i,rec] of data.entries()){
    const keys=Object.keys(rec).sort().join(",");
    if(keys!=="id,units,weight") throw new Error(r+" record "+i+" keys="+keys);
    if(!Number.isInteger(rec.id)||!Number.isInteger(rec.units)||!Number.isInteger(rec.weight)) throw new Error(r+" non-integer at "+i);
    if(rec.units<=0||rec.weight<=0) throw new Error(r+" non-positive at "+i);
    if(ids.has(rec.id)) throw new Error(r+" duplicate id "+rec.id);
    ids.add(rec.id);
    units+=rec.units; weighted+=rec.units*rec.weight;
  }
  const sorted=[...ids].sort((a,b)=>a-b);
  const contiguous=sorted.every((v,i)=>v===i+1);
  if(!contiguous) throw new Error(r+" ids not 1..n: "+sorted.join(","));
  const res={count:data.length,units,weighted};
  const insp=inspector[r];
  const match=res.count===insp.count&&res.units===insp.units&&res.weighted===insp.weighted;
  if(!match) ok=false;
  console.log(`region=${r} count=${res.count} units=${res.units} weighted=${res.weighted} ids=1..${sorted.length} inspector=${JSON.stringify(insp)} match=${match}`);
  out.regions[r]=res;
  out.grand_units+=res.units; out.grand_weighted+=res.weighted;
}
console.log("grand_units="+out.grand_units+" grand_weighted="+out.grand_weighted);
if(!ok){console.error("RECONCILIATION FAILED");process.exit(1);}
fs.writeFileSync("answer.json",JSON.stringify(out,null,2)+"\n");
console.log("WROTE answer.json");
console.log(fs.readFileSync("answer.json","utf8"));
'

