node <<'EOF'
const fs = require('fs');
const names = ['north','south','east','west'];
const expectedInspector = {
  north:{count:10,units:90,weighted:167},
  south:{count:10,units:94,weighted:171},
  east:{count:10,units:98,weighted:209},
  west:{count:10,units:85,weighted:145}
};
let fail = [];
const computed = {};
for (const n of names) {
  const data = JSON.parse(fs.readFileSync(n + '.json','utf8'));
  if (!Array.isArray(data)) throw new Error(n+' not array');
  if (data.length !== 10) fail.push(n+' length '+data.length);
  let units = 0, weighted = 0;
  const ids = [];
  for (const rec of data) {
    const k = Object.keys(rec).sort().join(',');
    if (k !== 'id,units,weight') fail.push(n+' keys '+k);
    for (const f of ['id','units','weight']) {
      if (!Number.isInteger(rec[f])) fail.push(n+' non-integer '+f);
    }
    if (!(rec.units > 0) || !(rec.weight > 0)) fail.push(n+' non-positive');
    ids.push(rec.id);
    units += rec.units;
    weighted += rec.units * rec.weight;
  }
  ids.sort((a,b)=>a-b);
  const contiguous = ids.every((v,i)=>v===i+1);
  if (!contiguous) fail.push(n+' ids not 1..n');
  computed[n] = {count:data.length, units, weighted};
  const e = expectedInspector[n];
  const match = computed[n].count===e.count && computed[n].units===e.units && computed[n].weighted===e.weighted;
  console.log(`${n}: count=${computed[n].count} units=${computed[n].units} weighted=${computed[n].weighted} ids=${ids[0]}..${ids[ids.length-1]} match_inspector=${match}`);
  if (!match) fail.push(n+' inspector mismatch');
}
const gu = names.reduce((s,n)=>s+computed[n].units,0);
const gw = names.reduce((s,n)=>s+computed[n].weighted,0);
console.log('grand_units='+gu+' grand_weighted='+gw);

const a = JSON.parse(fs.readFileSync('answer.json','utf8'));
const top = Object.keys(a).sort().join(',');
const rk = Object.keys(a.regions);
console.log('answer top_keys='+top);
console.log('answer region_keys='+rk.join(','));
console.log('answer exact 4-region set='+(rk.length===4 && ['north','south','east','west'].every(r=>rk.includes(r))));
for (const n of names) {
  const v = a.regions[n];
  const ek = Object.keys(v).sort().join(',');
  const ok = ek==='count,units,weighted' && v.count===computed[n].count && v.units===computed[n].units && v.weighted===computed[n].weighted;
  console.log(`answer.${n}: keys=${ek} values=${v.count}/${v.units}/${v.weighted} matches_recompute=${ok}`);
  if (!ok) fail.push('answer.'+n+' mismatch');
}
console.log('answer.grand_units='+a.grand_units+' matches='+(a.grand_units===gu));
console.log('answer.grand_weighted='+a.grand_weighted+' matches='+(a.grand_weighted===gw));
if (a.grand_units!==gu) fail.push('grand_units');
if (a.grand_weighted!==gw) fail.push('grand_weighted');
if (top!=='grand_units,grand_weighted,regions') fail.push('top keys');
console.log('FAILURES='+(fail.length?JSON.stringify(fail):'none'));
process.exit(fail.length?1:0);
EOF

